\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{positioning,shapes,backgrounds,calc}
\pagestyle{empty}

% ── Dark Bloomberg-Inspired Color Theme ──
\definecolor{bgposter}{HTML}{080C14}
\definecolor{primary}{HTML}{111827}
\definecolor{secondary}{HTML}{3B82F6}
\definecolor{accent}{HTML}{F59E0B}
\definecolor{accent2}{HTML}{10B981}
\definecolor{accent3}{HTML}{EF4444}
\definecolor{textlight}{HTML}{F1F5F9}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{textmuted}{HTML}{64748B}
\definecolor{cardbg}{HTML}{111B2A}
\definecolor{cardheadbg}{HTML}{162032}
\definecolor{statbg}{HTML}{151F33}
\definecolor{barblue}{HTML}{2563EB}
\definecolor{bargold}{HTML}{F59E0B}
\definecolor{barblue2}{HTML}{3B82F6}
\definecolor{barlight}{HTML}{60A5FA}
\definecolor{gridline}{HTML}{1F2A3C}
\definecolor{rowalt}{HTML}{0E1624}
\definecolor{tagtech}{HTML}{2563EB}
\definecolor{tagenergy}{HTML}{F59E0B}
\definecolor{tagconglom}{HTML}{8B5CF6}
\definecolor{tagauto}{HTML}{10B981}
\definecolor{tagchip}{HTML}{60A5FA}
\definecolor{tagweb}{HTML}{38BDF8}
\definecolor{tagconsumer}{HTML}{A78BFA}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Card styles for dark theme ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardheadbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.3},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardheadbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.3},
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent2},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent2},
    coltitle=accent2, colbacktitle=cardheadbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent2!50},
    valign=top, drop shadow={opacity=0.3},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!12!bgposter,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.35},
  },
}

% ── Section divider ──
\newcommand{\dividerline}{%
  \begin{center}\textcolor{gridline}{\rule{0.92\linewidth}{1pt}}\end{center}}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════════
% TITLE BAR (rows 0–4)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5},
  borderline south={4pt}{0pt}{secondary!80},
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{84}\selectfont\bfseries THE WORLD'S MOST VALUABLE}\\[6pt]
  {\fontsize{72}{84}\selectfont\bfseries\color{secondary} COMPANIES IN 2025}\\[16pt]
  {\fontsize{28}{36}\selectfont\color{textgray} A Comparative Snapshot of the Top 20 Publicly Traded Companies by Market Capitalization}\\[10pt]
  {\fontsize{24}{30}\selectfont\color{textmuted} Data as of Mid-2025 \quad$\bullet$\quad 10{,}796 Companies Tracked \quad$\bullet$\quad \$142.9T Total Global Market Cap}
}

% ═══════════════════════════════════════════════════════════════
% STAT BANNER (rows 4–6) — 3 headline metrics
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2pt}{0pt}{secondary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{accent!15!bgposter}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{accent}\$4.82T}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray}NVIDIA — World's \#1}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{secondary!15!bgposter}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{secondary}\$25.4T}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray}Top 10 Combined Value}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent2!40}{accent2!15!bgposter}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{accent2}15/20}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray}U.S. Companies in Top 20}\vspace{6pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════════
% TRILLION-DOLLAR CLUB — Full-width horizontal bar chart (rows 6–13)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=18pt, right=18pt, top=8pt, bottom=8pt,
  fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
  coltitle=accent, colbacktitle=cardheadbg,
  toptitle=8pt, bottomtitle=8pt,
  titlerule=2pt, titlerule style={accent!60},
  valign=top, drop shadow={opacity=0.3},
  title={THE TRILLION-DOLLAR CLUB \hfill \fontsize{28}{34}\selectfont\color{textmuted}11 companies have crossed \$1T market cap},
]{name=trillion, column=1, span=3, between=row6 and row13}{
  \vspace{4pt}
  % Top 5 highlight
  \colorbox{secondary!12!bgposter}{\parbox{0.97\linewidth}{\vspace{6pt}
    \centering
    {\fontsize{26}{32}\selectfont\color{textgray}TOP 5 COMBINED: }
    {\fontsize{30}{38}\selectfont\bfseries\color{secondary}\$18.5T \quad}
    {\fontsize{26}{32}\selectfont\color{textmuted}— roughly 13\% of all tracked public company value}\vspace{6pt}
  }}
  \vspace{6pt}

  % Horizontal bar chart using TikZ
  \begin{center}
  \begin{tikzpicture}[
    xscale=1, yscale=1,
    bar/.style={rounded corners=2pt},
  ]
    % Chart dimensions
    \def\chartwidth{730}
    \def\maxval{4.820}
    \def\barscale{\chartwidth/\maxval mm}% mm per trillion
    \def\barheight{18}

    % Grid lines
    \foreach \x in {1,2,3,4} {
      \pgfmathsetmacro{\xpos}{\x * \chartwidth/\maxval * 0.25}
      \draw[gridline, thin] (\xpos mm, 0.5) -- (\xpos mm, -12.5);
    }

    % ===== 1. NVIDIA =====
    \fill[accent, bar] (0,0) rectangle ({4.820*\barscale mm}, -\barheight mm);
    \node[anchor=east, text=textlight, font=\fontsize{30}{36}\selectfont\bfseries] at (-6pt,{-0.5*\barheight mm}) {1};
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont] at (-6pt,{-0.5*\barheight mm-11mm}) {\footnotesize\color{textmuted}NVDA};
    \node[anchor=west, text=accent, font=\fontsize{30}{36}\selectfont\bfseries] at ({4.820*\barscale mm + 6pt}, {-0.5*\barheight mm}) {\$4.820T};

    % ===== 2. Alphabet =====
    \fill[secondary, bar] (0,{-1.8}) rectangle ({4.025*\barscale mm}, {-1.8-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-6pt,{-1.8-0.5*\barheight mm}) {2};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont] at (-6pt,{-1.8-0.5*\barheight mm-10mm}) {\footnotesize\color{textmuted}GOOG};
    \node[anchor=west, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at ({4.025*\barscale mm + 6pt}, {-1.8-0.5*\barheight mm}) {\$4.025T};

    % ===== 3. Apple =====
    \fill[barblue2, bar] (0,{-3.6}) rectangle ({3.871*\barscale mm}, {-3.6-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-6pt,{-3.6-0.5*\barheight mm}) {3};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont] at (-6pt,{-3.6-0.5*\barheight mm-10mm}) {\footnotesize\color{textmuted}AAPL};
    \node[anchor=west, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at ({3.871*\barscale mm + 6pt}, {-3.6-0.5*\barheight mm}) {\$3.871T};

    % ===== 4. Microsoft =====
    \fill[barblue, bar] (0,{-5.4}) rectangle ({3.123*\barscale mm}, {-5.4-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-6pt,{-5.4-0.5*\barheight mm}) {4};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont] at (-6pt,{-5.4-0.5*\barheight mm-10mm}) {\footnotesize\color{textmuted}MSFT};
    \node[anchor=west, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at ({3.123*\barscale mm + 6pt}, {-5.4-0.5*\barheight mm}) {\$3.123T};

    % ===== 5. Amazon =====
    \fill[barblue!80, bar] (0,{-7.2}) rectangle ({2.685*\barscale mm}, {-7.2-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-6pt,{-7.2-0.5*\barheight mm}) {5};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont] at (-6pt,{-7.2-0.5*\barheight mm-10mm}) {\footnotesize\color{textmuted}AMZN};
    \node[anchor=west, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at ({2.685*\barscale mm + 6pt}, {-7.2-0.5*\barheight mm}) {\$2.685T};

    % ── Tier divider line ──
    \draw[accent!40, dashed, thick] (0,{-8.3}) -- ({\chartwidth mm}, {-8.3});
    \node[anchor=west, text=accent, font=\fontsize{20}{26}\selectfont] at (2pt, {-8.7}) {\$2T threshold gap};

    % ===== 6. Broadcom =====
    \fill[barblue!60, bar] (0,{-9.2}) rectangle ({1.889*\barscale mm}, {-9.2-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-6pt,{-9.2-0.5*\barheight mm}) {6};
    \node[anchor=east, text=textgray, font=\fontsize{22}{28}\selectfont] at (-6pt,{-9.2-0.5*\barheight mm-9mm}) {\footnotesize\color{textmuted}AVGO};
    \node[anchor=west, text=textgray, font=\fontsize{26}{32}\selectfont\bfseries] at ({1.889*\barscale mm + 6pt}, {-9.2-0.5*\barheight mm}) {\$1.889T};

    % ===== 7. TSMC =====
    \fill[barblue!60, bar] (0,{-10.9}) rectangle ({1.884*\barscale mm}, {-10.9-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-6pt,{-10.9-0.5*\barheight mm}) {7};
    \node[anchor=east, text=textgray, font=\fontsize{22}{28}\selectfont] at (-6pt,{-10.9-0.5*\barheight mm-9mm}) {\footnotesize\color{textmuted}TSM};
    \node[anchor=west, text=textgray, font=\fontsize{26}{32}\selectfont\bfseries] at ({1.884*\barscale mm + 6pt}, {-10.9-0.5*\barheight mm}) {\$1.884T};

    % ===== 8. Saudi Aramco =====
    \fill[accent!70, bar] (0,{-12.6}) rectangle ({1.774*\barscale mm}, {-12.6-\barheight mm});
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-6pt,{-12.6-0.5*\barheight mm}) {8};
    \node[anchor=east, text=textgray, font=\fontsize{22}{28}\selectfont] at (-6pt,{-12.6-0.5*\barheight mm-9mm}) {\footnotesize\color{textmuted}2222.SR};
    \node[anchor=west, text=textgray, font=\fontsize{26}{32}\selectfont\bfseries] at ({1.774*\barscale mm + 6pt}, {-12.6-0.5*\barheight mm}) {\$1.774T};

    % % ===== 9. Meta =====
    % \fill[barblue!50, bar] (0,{-14.3}) rectangle ({1.712*\barscale mm}, {-14.3-\barheight mm});
    % \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-6pt,{-14.3-0.5*\barheight mm}) {9};
    % \node[anchor=east, text=textgray, font=\fontsize{22}{28}\selectfont] at (-6pt,{-14.3-0.5*\barheight mm-9mm}) {\footnotesize\color{textmuted}META};
    % \node[anchor=west, text=textgray, font=\fontsize{26}{32}\selectfont\bfseries] at ({1.712*\barscale mm + 6pt}, {-14.3-0.5*\barheight mm}) {\$1.712T};

    % % ===== 10. Tesla =====
    % \fill[barblue!40, bar] (0,{-16.0}) rectangle ({1.459*\barscale mm}, {-16.0-\barheight mm});
    % \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-6pt,{-16.0-0.5*\barheight mm}) {10};
    % \node[anchor=east, text=textgray, font=\fontsize{22}{28}\selectfont] at (-6pt,{-16.0-0.5*\barheight mm-9mm}) {\footnotesize\color{textmuted}TSLA};
    % \node[anchor=west, text=textgray, font=\fontsize{26}{32}\selectfont\bfseries] at ({1.459*\barscale mm + 6pt}, {-16.0-0.5*\barheight mm}) {\$1.459T};

    % ===== Company names (left column) =====
    \node[anchor=east, text=textlight, font=\fontsize{30}{36}\selectfont\bfseries] at (-60pt,{-0.5*\barheight mm}) {NVIDIA};
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-60pt,{-1.8-0.5*\barheight mm}) {Alphabet};
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-60pt,{-3.6-0.5*\barheight mm}) {Apple};
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-60pt,{-5.4-0.5*\barheight mm}) {Microsoft};
    \node[anchor=east, text=textlight, font=\fontsize{28}{34}\selectfont\bfseries] at (-60pt,{-7.2-0.5*\barheight mm}) {Amazon};
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-60pt,{-9.2-0.5*\barheight mm}) {Broadcom};
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-60pt,{-10.9-0.5*\barheight mm}) {TSMC};
    \node[anchor=east, text=textlight, font=\fontsize{26}{32}\selectfont\bfseries] at (-60pt,{-12.6-0.5*\barheight mm}) {Saudi Aramco};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont\bfseries] at (-60pt,{-14.3-0.5*\barheight mm}) {Meta};
    \node[anchor=east, text=textgray, font=\fontsize{24}{30}\selectfont\bfseries] at (-60pt,{-16.0-0.5*\barheight mm}) {Tesla};
  \end{tikzpicture}
  \end{center}

  % Bottom annotation
  \vspace{2pt}
  \colorbox{accent!12!bgposter}{\parbox{0.97\linewidth}{\vspace{4pt}\centering
    {\fontsize{24}{30}\selectfont\color{textgray}Rank 1 (\$4.82T) to Rank 20 (\$554B) = }
    {\fontsize{26}{32}\selectfont\bfseries\color{accent}9$\times$ drop in valuation}
    \hspace{20pt}
    {\fontsize{24}{30}\selectfont\color{textgray}Top 10 = }
    {\fontsize{26}{32}\selectfont\bfseries\color{secondary}17.8\%}
    {\fontsize{24}{30}\selectfont\color{textgray} of all tracked value}
  \vspace{4pt}}}
}

% ═══════════════════════════════════════════════════════════════
% ROW BAND 2 — Country, Sector, Context (rows 13–18)
% ═══════════════════════════════════════════════════════════════

% ── Column 1: Country & Regional Dominance ──
\posterbox[goldcard, title={COUNTRY \& REGIONAL DOMINANCE}
]{name=country, column=1, between=row13 and row18}{
  \fontsize{28}{36}\selectfont
  \vspace{2pt}

  % USA bar
  \colorbox{secondary!15!bgposter}{\parbox{0.94\linewidth}{\vspace{5pt}\centering
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary}15 of Top 20 are U.S. Companies}
  \vspace{5pt}}}

  \vspace{4pt}

  {\fontsize{26}{32}\selectfont\color{textgray}Remaining 5 from 5 different countries:}

  \vspace{3pt}
  \begin{itemize}[itemsep=10pt, leftmargin=18pt]
    \item {\bfseries\color{textlight}Taiwan} — TSMC (\$1.884T)
    \item {\bfseries\color{textlight}Saudi Arabia} — Saudi Aramco (\$1.774T)
    \item {\bfseries\color{textlight}South Korea} — Samsung
    \item {\bfseries\color{textlight}China} — Tencent (Rank 18)
    \item {\bfseries\color{textlight}Netherlands} — ASML (Rank 20)
